head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/**
 * @method
 * @name left_menu_open
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.left_menu_open = function() {
    document.all.left_open.style.display = "none";
    document.all.left_close.style.display = "";
    document.all.left_menu_div.style.display = "";
};
/**
 * @method
 * @name left_menu_close
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.left_menu_close = function() {
    document.all.left_open.style.display = "";
    document.all.left_close.style.display = "none";
    document.all.left_menu_div.style.display = "none";
};
/**
 * @method
 * @name submission_left_menu_open
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.submission_left_menu_open = function() {
    document.all.left_open.style.display = "none";
    document.all.left_close.style.display = "";
    document.all.left_menu_div.style.display = "";
    if (document.all.submission_top != null) {
        document.all.submission_top.style.display = "";
        document.all.editorDiv.style.setGridHeight("600px");
    }
    if (typeof document.all.edit_btn != 'undefined') {
        document.all.edit_btn.addClass("btn_w4 fs12 bg_icon1");
        document.all.edit_btn.setValue("보고서 확장");
    }
    scwin.editorSizeMax = false;
};
/**
 * @method
 * @name submission_left_menu_close
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.submission_left_menu_close = function() {
    document.all.left_open.style.display = "";
    document.all.left_close.style.display = "none";
    document.all.left_menu_div.style.display = "none";
    if (document.all.submission_top != null) {
        document.all.submission_top.style.display = "none";
        document.all.editorDiv.style.setGridHeight("750px");
    }
    if (typeof document.all.edit_btn != 'undefined') {
        document.all.edit_btn.addClass("btn_w4 fs12 bg_icon1_1");
        document.all.edit_btn.setValue("보고서 축소");
    }
    scwin.editorSizeMax = true;
};
editorSizeMax = false;
/**
 * @method
 * @name editorSizeChange
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.editorSizeChange = function() {
    if (scwin.editorSizeMax) {
        scwin.submission_left_menu_open();
    } else {
        scwin.submission_left_menu_close();
    }
};
